using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;
using System.Text.Unicode;
using System.Threading.Tasks;

namespace tounsiYoyo.Model
{
    public class Business
    {
        public string ID { get; set; } = string.Empty;
        public string Name { get; set; } = string.Empty;
        public string Logo { get; set; } = "data:image/jpeg;base64,";
        public Special special { get; set; } = null!;
        
        public Business(string ID, string Name, Special special)
        {
            this.ID = ID;
            this.Name = Name;
            Logo = Logo;
            this.special = special;
        }
        private static readonly JsonSerializerOptions JsonOptions = new()
        {
            // indente le josn sur plusieurs lignes pour qu'il soit lisible
            WriteIndented = true,
            // encode correctment avec les accents
            Encoder = JavaScriptEncoder.Create(UnicodeRanges.All),
        };
        public void Export(string? path = null)
        {
            string json = JsonSerializer.Serialize(this, JsonOptions);
            string targetPath = path ?? JsonPathResolver.ResolvePath();
            File.WriteAllText(targetPath, json);
        }
    }
}
